# efc.pv  (ignition/script-python/efc/pv/code.py) - on-screen process values and the trends overview. Generated by
# generator/docks/build_docks.py. Ignition 8.1.22+ (Jython 2.7), 8.3 compatible. Decision 35.
#
# Perspective cannot list the templates on a page from one place (component traversal stops at a view boundary), so
# every process-value template announces itself: its root onStartup calls efc.pv.register(self), onShutdown calls
# efc.pv.unregister(self) and a change script on params.tagPath calls efc.pv.rebind(self, previousValue, currentValue).
# The registry lives in gateway memory (system.util.getGlobals(), a ConcurrentHashMap per page, keyed
# '<sessionId>|<pageId>') because parallel template scripts would lose entries in a session.custom list.
# The trends overview (Templates/Dynamic Window/TrendsOverview, the dock's default view) reads the registry, groups
# the values by variable type from their engineering unit, and writes one Power Chart plot per type.
#   template root onStartup:         efc.pv.register(self)
#   template root onShutdown:        efc.pv.unregister(self)
#   params.tagPath change script:    efc.pv.rebind(self, previousValue, currentValue)
#   overview poll / message:         efc.pv.refresh(self)
#   Session Shutdown event:          efc.pv.purgeSession(session.props.id)

REGISTRY_KEY = 'efc.pv.registry'
MESSAGE = 'efc.pvChanged'                      # page-scope hint sent after every change; the registry is the state
MAX_PLOTS, MAX_PENS = 6, 8

# Members per template type: pv is the historized value, sp an optional second pen, eu / tag / desc the labels
MEMBERS = {
    'T_AI':  {'pv': 'Val_PV', 'eu': 'Cfg_EU', 'tag': 'Cfg_Tag', 'desc': 'Cfg_Desc'},
    'T_KPI': {'pv': 'Val_PV', 'eu': 'Cfg_EU', 'tag': 'Cfg_Tag', 'desc': 'Cfg_Desc'},
    'T_PID': {'pv': 'Val_PV', 'sp': 'Val_SP', 'eu': 'Cfg_PVEU', 'tag': 'Cfg_Tag', 'desc': 'Cfg_Desc'},
    'T_Analyzer': {'pv': 'Val_PV', 'eu': 'Cfg_EU', 'tag': 'Cfg_Tag', 'desc': 'Cfg_Desc'},
}

# Variable types in display order: (key, label, engineering-unit tokens after norm_eu). First match wins.
VAR_TYPES = [
    ('pressure', 'Pressure', ['psi', 'psig', 'psia', 'bar', 'barg', 'bara', 'mbar', 'kpa', 'kpag', 'mpa', 'pa', 'inhg', 'mmhg', 'torr', 'atm', 'kg/cm2']),
    ('dp', 'Differential pressure', ['psid', 'inh2o', 'inwc', '"wc', 'mmh2o', 'mmwc', 'kpad', 'mbard', 'bard']),
    ('temperature', 'Temperature', ['degf', 'degc', 'f', 'c', 'k', 'degk', 'degr']),
    ('flow', 'Flow', ['gpm', 'gph', 'mgd', 'l/s', 'l/min', 'lpm', 'l/h', 'lph', 'm3/h', 'm3/s', 'm3/d', 'cfm', 'scfm', 'acfm',
                      'scfh', 'nm3/h', 'sm3/h', 'ft3/min', 'bbl/d', 'kg/h', 'kg/s', 'kg/min', 't/h', 'lb/h', 'lb/min', 'pph', 'slpm', 'sccm']),
    ('level', 'Level', ['%lvl', 'inlvl', 'mmlvl']),
    ('analysis', 'Analysis', ['ph', 'ms/cm', 'us/cm', 'µs/cm', 'ntu', 'ppm', 'ppb', 'mg/l', 'ug/l', '%o2', '%lel', 'orp', 'mv']),
    ('speed', 'Speed', ['rpm', 'hz', 'm/s', 'ft/min', 'fpm']),
    ('electrical', 'Electrical', ['a', 'ma', 'kw', 'mw', 'w', 'hp', 'kva', 'kvar', 'v', 'kv']),
    ('weight', 'Weight', ['kg', 'g', 't', 'lb', 'lbs', 'ton', 'oz']),
    ('volume', 'Volume', ['m3', 'l', 'gal', 'bbl', 'ft3', 'ml']),
    ('vibration', 'Vibration', ['mm/s', 'in/s', 'ips', 'gs', 'mils']),
    ('percent', 'Percent', ['%', 'pct']),
    ('length', 'Length / position', ['m', 'cm', 'mm', 'ft', 'in', 'deg']),
    ('other', 'Other', []),
]
# ISA-5.1 first letter of the tag name, used when the unit is ambiguous or missing
ISA_LETTER = {'P': 'pressure', 'T': 'temperature', 'F': 'flow', 'L': 'level', 'A': 'analysis', 'S': 'speed',
              'I': 'electrical', 'E': 'electrical', 'J': 'electrical', 'W': 'weight', 'V': 'vibration', 'Z': 'length'}
AMBIGUOUS = ('percent', 'length', 'other')
# Up to MAX_PENS pens per plot: ISA-101 greys first, the setpoint blue, then dashes (stroke, dash array)
PEN_STYLES = [('#1F1F1F', ''), ('#1F4E99', ''), ('#7F7F7F', ''), ('#1F1F1F', '6,3'), ('#1F4E99', '6,3'),
              ('#7F7F7F', '6,3'), ('#1F1F1F', '2,2'), ('#1F4E99', '2,2')]


def _log():
    return system.util.getLogger('efc.pv')


def _p(params, name, default=None):
    try:
        v = getattr(params, name)
    except Exception:
        try:
            v = params[name]
        except Exception:
            return default
    return default if v is None else v


# ----------------------------------------------------------------- engineering unit -> variable type
def norm_eu(eu):
    """Normalise an engineering-unit string for the VAR_TYPES lookup: 'Deg F' / '°F' -> 'degf', 'in H2O' -> 'inh2o'."""
    s = (eu or '').strip().lower()
    for a, b in ((u'\xb0', 'deg'), ('deg.', 'deg'), ('degrees', 'deg'), ('degree', 'deg'), (' ', ''), ('_', ''), ('^', '')):
        s = s.replace(a, b)
    return s


def var_type(eu, tag=''):
    """Variable type key for an engineering unit, with the ISA letter of the tag name as the tie-break."""
    s = norm_eu(eu)
    found = 'other'
    for key, _, tokens in VAR_TYPES:
        if s and s in tokens:
            found = key
            break
    if found in AMBIGUOUS:
        letter = (tag or '').strip()[:1].upper()
        if letter in ISA_LETTER:
            return ISA_LETTER[letter]
    return found


def type_label(key):
    for k, label, _ in VAR_TYPES:
        if k == key:
            return label
    return 'Other'


# ----------------------------------------------------------------- registry
def _registry():
    g = system.util.getGlobals()
    reg = g.get(REGISTRY_KEY)
    if reg is None:
        try:
            from java.util.concurrent import ConcurrentHashMap
            reg = ConcurrentHashMap()
        except ImportError:                    # CPython test harness
            reg = {}
        g[REGISTRY_KEY] = reg
    return reg


def _page_map(key, create):
    reg = _registry()
    m = reg.get(key)
    if m is None and create:
        try:
            from java.util.concurrent import ConcurrentHashMap
            m = ConcurrentHashMap()
        except ImportError:
            m = {}
        prev = reg.putIfAbsent(key, m) if hasattr(reg, 'putIfAbsent') else reg.setdefault(key, m)
        if prev is not None and prev is not m:
            m = prev
    return m


def _key(component):
    return '%s|%s' % (component.session.props.id, component.page.props.pageId)


def _notify(component):
    try:
        system.perspective.sendMessage(MESSAGE, payload={}, scope='page',
                                      sessionId=component.session.props.id, pageId=component.page.props.pageId)
    except Exception as e:
        _log().debug('notify: %s' % e)


def _entry(tagPath, tType, page):
    """Registry entry for one template instance; labels are read once from the tag (they are Cfg_ members)."""
    mem = MEMBERS.get(tType) or MEMBERS['T_AI']
    paths = [tagPath + '/' + mem['eu'], tagPath + '/' + mem['tag'], tagPath + '/' + mem['desc']]
    eu = tag = desc = ''
    try:
        vals = system.tag.readBlocking(paths)
        eu, tag, desc = [str(q.value) if q.value is not None else '' for q in vals]
    except Exception as e:
        _log().debug('register %s: %s' % (tagPath, e))
    pens = [{'name': tag or tagPath.rsplit('/', 1)[-1], 'path': tagPath + '/' + mem['pv'], 'kind': 'pv'}]
    if mem.get('sp'):
        pens.append({'name': (tag or tagPath.rsplit('/', 1)[-1]) + ' SP', 'path': tagPath + '/' + mem['sp'], 'kind': 'sp'})
    return {'tagPath': tagPath, 'tType': tType, 'page': page, 'eu': eu, 'tag': tag, 'desc': desc,
            'type': var_type(eu, tag), 'pens': pens}


def register(component, tagPath=None):
    """Template root onStartup: add this instance's process value to the page registry.
    Skipped when params.census is false (templates inside dynamic windows and popups) or tagPath is empty."""
    p = component.view.params
    if not _p(p, 'census', True):
        return
    tp = tagPath or _p(p, 'tagPath') or ''
    if not tp:
        return
    tType = _p(p, 'tType', 'T_AI')
    m = _page_map(_key(component), True)
    m.put(tp, _entry(tp, tType, component.page.props.path)) if hasattr(m, 'put') else m.__setitem__(tp, _entry(tp, tType, component.page.props.path))
    _notify(component)


def unregister(component, tagPath=None):
    """Template root onShutdown: remove this instance from the page registry."""
    tp = tagPath or _p(component.view.params, 'tagPath') or ''
    m = _page_map(_key(component), False)
    if m is None or not tp:
        return
    if m.remove(tp) if hasattr(m, 'remove') else m.pop(tp, None):
        _notify(component)


def _val(q):
    """QualifiedValue (change-script arguments) -> value."""
    return getattr(q, 'value', q)


def rebind(component, previous, current):
    """params.tagPath change script: a reused view gets new params without onStartup firing again.
    On a view-param change script `self` is the view, so the root container stands in as the component."""
    if not hasattr(component, 'view'):
        component = component.rootContainer
    previous, current = _val(previous), _val(current)
    if previous:
        unregister(component, str(previous))
    if current:
        register(component, str(current))


def purgeSession(sessionId):
    """Session Shutdown gateway event: drop every page of the closed session (closing a tab does not shut views down)."""
    reg = _registry()
    for k in list(reg.keySet() if hasattr(reg, 'keySet') else reg.keys()):
        if str(k).startswith(str(sessionId) + '|'):
            reg.remove(k) if hasattr(reg, 'remove') else reg.pop(k, None)


def entries(component):
    """Registry entries for this page, current screen only (pageId survives navigate(); the page path does not)."""
    m = _page_map(_key(component), False)
    if m is None:
        return []
    page = component.page.props.path
    vals = list(m.values())
    out = [dict(e) for e in vals if e.get('page') == page]
    out.sort(key=lambda e: (e.get('tag') or e['tagPath']).lower())
    return out


def signature(entries_):
    return '|'.join(e['tagPath'] + '=' + e['type'] for e in entries_)


# ----------------------------------------------------------------- grouping and chart config
def groups(entries_, maxPlots=MAX_PLOTS, maxPens=MAX_PENS):
    """[{'type', 'label', 'eu', 'pens': [...]}] in VAR_TYPES order; the EU shown is the group's most common unit."""
    by = {}
    for e in entries_:
        by.setdefault(e['type'], []).append(e)
    out = []
    for key, label, _ in VAR_TYPES:
        if key not in by:
            continue
        items = by[key]
        eus = {}
        for e in items:
            eus[e['eu']] = eus.get(e['eu'], 0) + 1
        eu = sorted(eus.items(), key=lambda kv: -kv[1])[0][0] if eus else ''
        pens = []
        for e in items:
            for pen in e['pens']:
                pens.append(dict(pen, eu=e['eu'], desc=e['desc']))
        out.append({'type': key, 'label': label, 'eu': eu, 'pens': pens[:maxPens], 'dropped': max(0, len(pens) - maxPens)})
    return out[:maxPlots]


def _pen_style(color, dash, width, opacity):
    return {'stroke': {'color': color, 'width': width, 'dashArray': dash or 0, 'opacity': opacity},
            'fill': {'color': color, 'opacity': 0}}


def chart(groups_, rangeMinutes=30):
    """Power Chart props (plots, axes, pens) for the grouped values: one plot and one left axis per variable type.
    Property names per the 8.1 Power Chart schema; pen sources are plain tag paths (converted by the chart, 8.1.14+)."""
    plots, axes, pens = [], [], []
    for i, g in enumerate(groups_):
        axis = '%s_%d' % (g['type'], i)
        axes.append({'name': axis, 'position': 'left', 'width': 48, 'color': '#7F7F7F', 'dataFormat': '0,0.#',
                     'range': {'auto': True, 'min': '', 'max': ''},
                     'label': {'text': g['eu'] or g['label'], 'offset': 0, 'font': {'color': '#1F1F1F', 'size': 11}, 'style': {'classes': ''}},
                     'tick': {'color': '#7F7F7F', 'count': 'Auto', 'label': {'font': {'color': '#1F1F1F', 'size': 10}, 'format': 'Auto',
                                                                            'style': {'classes': ''}}, 'style': {'classes': ''}},
                     'grid': {'visible': True, 'color': '#C4C4C4', 'opacity': 0.6, 'dashArray': 2, 'style': {'classes': ''}},
                     'style': {'classes': ''}})
        plots.append({'relativeWeight': 1, 'color': '#FFFFFF00', 'markers': [], 'style': {'classes': ''}})
        for j, pen in enumerate(g['pens']):
            stroke, dash = PEN_STYLES[j % len(PEN_STYLES)]
            if pen.get('kind') == 'sp':
                stroke, dash = '#1F4E99', '6,3'
            pens.append({'name': pen['name'], 'visible': True, 'enabled': True, 'selectable': False, 'axis': axis, 'plot': i,
                         'display': {'type': 'line', 'interpolation': 'curveLinear', 'breakLine': True, 'radius': 3,
                                     'styles': {'normal': _pen_style(stroke, dash, 1.5, 1), 'highlighted': _pen_style(stroke, dash, 2.5, 1),
                                                'selected': _pen_style(stroke, dash, 2.5, 1), 'muted': _pen_style(stroke, dash, 1.5, 0.4)}},
                         'data': {'source': pen['path'], 'aggregateMode': 'default'}})
    return {'plots': plots, 'axes': axes, 'pens': pens, 'unitOfTime': int(rangeMinutes), 'measureOfTime': 'minutes'}


def setRange(component, minutes):
    """Overview range button: realtime window of the chart (5 .. 1440 min)."""
    view = component.view
    view.custom.range = int(minutes)
    ch = view.rootContainer.getChild('Chart')
    ch.props.config.mode = 'realtime'
    ch.props.config.unitOfTime = int(minutes)
    ch.props.config.measureOfTime = 'minutes'


def refresh(component, force=False):
    """Overview view: rebuild the chart when the set of on-screen values changed (poll, message or startup).
    `component` is the overview's root; the chart is its child named 'Chart'."""
    ents = entries(component)
    sig = signature(ents)
    view = component.view
    try:
        if not force and view.custom.sig == sig:
            return False
    except Exception:
        pass
    gs = groups(ents)
    cfg = chart(gs, _p(view.custom, 'range', 30))
    ch = component.getChild('Chart')
    ch.props.pens = []                     # clear first: a pen whose plot index changes keeps its old axis row otherwise
    ch.props.axes = cfg['axes']
    ch.props.plots = cfg['plots']
    ch.props.pens = cfg['pens']
    view.custom.sig = sig
    view.custom.count = len(ents)
    view.custom.groups = [{'label': g['label'], 'eu': g['eu'], 'n': len(g['pens']), 'dropped': g['dropped']} for g in gs]
    return True
